def longestDiverseString(a, b, c):
    def append_char(char, count, result):
        if count == 0:
            return result, count
        if len(result) >= 2 and result[-1] == result[-2] == char:
            return result, count
        add = min(2, count)
        result += char * add
        return result, count - add

    result = ""
    while a > 0 or b > 0 or c > 0:
        if (a >= b and a >= c) or (a > 0 and (result[-2:] != "aa" if len(result) >= 2 else True)):
            result, a = append_char('a', a, result)
        elif (b >= a and b >= c) or (b > 0 and (result[-2:] != "bb" if len(result) >= 2 else True)):
            result, b = append_char('b', b, result)
        elif (c >= a and c >= b) or (c > 0 and (result[-2:] != "cc" if len(result) >= 2 else True)):
            result, c = append_char('c', c, result)
        else:
            break
    return result
